import string

def word_frequency(text: str) -> dict[str, int]:
    freq = {}
    for word in text.split():
        clean_word = word.lower().strip(string.punctuation)
        if clean_word:
            freq[clean_word] = freq.get(clean_word, 0) + 1
    return freq
